{"charges": [{"claim": "The change increases the minimum length of the subdomain label after 'www.' from 1 to 2, causing single-character subdomains like 'www.a.com' to not have 'www.' stripped when stripWWW is true.", "file": "index.js", "line": 205, "severity": "major", "witnessCode": "import { strict as assert } from 'node:assert';
import normalizeUrl from '../index.js';

const input = 'http://www.a.com';
const options = { stripWWW: true };
const expected = 'http://a.com';
const actual = normalizeUrl(input, options);
assert.strictEqual(actual, expected);"}]}
